            ejectionBankSlotConfig.EjectionConfig.DeviationWithEjectionCenterAndWaferCameraCenter.Z);

    if (AKRSXtraMessageBox.Show("是否需要做顶针中心模板？", "提示", MessageBoxButtons.YesNo, MessageBoxIcon.Information)
