private void InitControl()
{
    TUAssistantHelper.SetColor(this.TileBarTeach);

    this.PnlControl.Controls.Add(ucGuideMove1);

    this.assistantConfigList
        = new List<AssistantConfig>
        {
            // 第一点
            new AssistantConfig(
                index: 0,
                descritpion: this.nozzle.NozzleShape == NozzleShapeEnum.Round ? "Step1/2:将相机中心对齐吸嘴中心。" : "Step1/2:将相机中心对齐吸嘴左上角。",
                isShowTitle: true,
                isShowBack: false,
                isShowNext: true,
                isShowDone: false,
                backAction: () =>
                {
                },
                nextAction: () =>
                    {
                        this.TileBarTeach.SelectedItem = this.TbiAlignCorner2;

                        if (MachineStateModel.GetInstance().MachineWorkMode == MachineWorkModeEnum.OffLineWork)
                        {
                            return;
                        }

                        this.nozzle.NozzleToUplookCenterPos = this.bondModuleController.GetG0RealPosition();

                        this.nozzle.AlignAngle = this.bondHeadController.GetAxisTRealPos();

                        // 记录当前坐标
                        this.wordPos1 = this.bondModuleController.Get2DRealPosition();

                        try
                        {
                            double angle = this.bondHeadController.GetAxisTRealPos();

                            if (this.bondHeadController.GetAxisTRealPos() <= 0)
                            {
                                // T轴转180度
                                this.bondHeadController.RotateAxisT(angle + 180);
                            }
                            else
                            {
                                // T轴转-180度
                                this.bondHeadController.RotateAxisT(angle - 180);
                            }
                        }
                        catch (Exception e)
                        {
                            DialogResult dialog = AKRSXtraMessageBox.Show(
                                $"T轴旋转失败:" + e.ToString(),
                                "Error",
                                MessageBoxButtons.OK,
                                MessageBoxIcon.Error);

                            throw e;
                        }
                    },
               doneAction: () =>
               {
               }),

            // 第二点
            new AssistantConfig(
                index: 1,
                descritpion: this.nozzle.NozzleShape == NozzleShapeEnum.Round ? "Step2/2:再将相机中心对齐吸嘴中心" : "Step2/2:再将相机中心对齐吸嘴右下角",
                isShowTitle: true,
                isShowBack: false,
                isShowNext: false,
                isShowDone: true,
                backAction: () =>
                {
                    //// T轴往回转180度
                    //this.bondHeadController.RelativeRotateAxisT(-180);

                    this.TileBarTeach.SelectedItem = this.TbiAlignCorner1;
                },
                nextAction: () =>
                {
                },
                doneAction: () =>
                {
                    if (MachineStateModel.GetInstance().MachineWorkMode == MachineWorkModeEnum.OffLineWork)
                    {
                        return;
                    }

                    if (this.nozzle.XYDeterminationMethod == XYDeterminationMethodEnum.UpLookingCamera)
                    {

                    }

                    // 记录当前坐标
                        this.wordPos2 = this.bondModuleController.Get2DRealPosition();

                        if (this.nozzle.NozzleShape == NozzleShapeEnum.Round)
                        {
                            // 计算结果
                            this.nozzle.NozzleOffset.X = (this.wordPos2.X - this.wordPos1.X) / 2;
                            this.nozzle.NozzleOffset.Y = (this.wordPos2.Y - this.wordPos1.Y) / 2;
                        }
                        else
                        {
                            // 计算结果
                            this.nozzle.RectangleNozzleCornerOffset.X = (this.wordPos2.X - this.wordPos1.X) / 2;
                            this.nozzle.RectangleNozzleCornerOffset.Y = (this.wordPos2.Y - this.wordPos1.Y) / 2;
                        }

                        AKRSPoint3D pos = new AKRSPoint3D()
                                              {
                                                  X = (this.wordPos2.X + this.wordPos1.X) / 2,
                                                  Y = (this.wordPos2.Y + this.wordPos1.Y) / 2,
                                                  Z = this.bondHeadController.GetAxisZRealPos()
                                              };

                        // 保存旋转中心
                        this.nozzle.RotateCenterPos = this.bondModuleController.ConvertMachineToG0Pos(pos);

                        this.nozzle.ToolAlignment.State = AssistantStateEnum.Able;

                        // 矩形吸嘴示教第二步必须示教第三步
                        if (this.nozzle.NozzleShape == NozzleShapeEnum.Rectangle)
                        {
                            this.nozzle.ToolGeometryAssistant.State = AssistantStateEnum.UnAble;
                        }

                        // 保存模板名称
                        //this.nozzle.PREntityName = this.frmPRList.VisionEntityName;
                }),
        };

    // 首个步骤的AssistantConfig
    this.SetUIControl(0);

    // 设置高亮
    this.TileBarTeach.SelectedItem = this.TbiAlignCorner1;

    // 方向盘设置模组名称
    ucGuideMove1.ChangeModuleName("上视模组", true);

    this.Size = new Size(749, 900);

