public void PrepareBeforePickOffsetAutoCali(BaseCarrierConfig component)
{
    // 寻找Pr模板
    PREntity pREntity = (PREntity)VisionEntityRepository.GetInstance().Find(component.UpLookAdjustConfig.P1PRName);

