                MessageBoxIcon.Information);
        }
        catch (Exception ex)
        {
            if (ex.Message.Contains("正由另一进程使用"))
            {
               AKRSXtraMessageBox.Show("数据导出失败！文件正由另一个程序占用！", "提示");
            }
            else
            {
               AKRSXtraMessageBox.Show("数据导出失败！数据量过大，请分别统计再导出！", "提示");
            }
        }
    }

    fileDialog.Dispose();
}

